#!/usr/bin/env ruby
# frozen_string_literal: true
# 使い方: Gemfile のあるフォルダーで ruby install_media_crud.rb
# このスクリプトは同梱コードを書き出すだけで、scaffold は使用しません。
require "base64"
require "fileutils"
require "json"
require "pathname"
require "ripper"

root = Pathname.pwd
required = %w[Gemfile bin/rails config/application.rb config/routes.rb app/models/application_record.rb]
missing = required.reject { |path| root.join(path).file? }
abort "Railsアプリの一番上（Gemfileがある場所）で実行してください。見つからないファイル: #{missing.join(', ')}" if missing.any?

other_models = Dir.glob(root.join("app/models/**/*.rb").to_s).reject do |path|
  path == root.join("app/models/application_record.rb").to_s || path.include?("/concerns/")
end
if other_models.any?
  abort "追加を中止しました。すでにモデルがあります（追加済みの場合も含みます）。\n#{other_models.join("\n")}\n既存ファイルは変更していません。すでに導入済みなら bin/rails db:migrate へ進んでください。"
end
if Dir.glob(root.join("db/migrate/*create_media_items*.rb").to_s).any? ||
   (root.join("db/schema.rb").file? && root.join("db/schema.rb").read.match?(/create_table\s+["']media_items["']/))
  abort "media_items の作成定義がすでにあります。重複作成を避けるため中止しました。"
end

routes_path = root.join("config/routes.rb")
original_routes = routes_path.read
route_header = /^Rails\.application\.routes\.draw do\s*$/
abort "config/routes.rb の形式を確認してください。何も変更していません。" unless original_routes.match?(route_header)
if original_routes.match?(/^\s*resources?\s*(?:\(?\s*)[:"']media_items\b/)
  abort "media_items のルーティングがすでにあります。何も変更していません。"
end
has_root = original_routes.match?(/^\s*root(?:\s|\()/)
new_routes = original_routes.sub(route_header) do |line|
  addition = "\n  # 画像・音楽管理: resources による7機能\n  resources :media_items\n"
  addition += "  root \"media_items#index\"\n" unless has_root
  line.rstrip + addition
end
abort "ルーティングの構文確認に失敗しました。何も変更していません。" unless Ripper.sexp(new_routes)

payload = JSON.parse(DATA.read)
timestamp = Time.now.utc.strftime("%Y%m%d%H%M%S")
targets = payload.fetch("files").to_h do |relative, encoded|
  relative = relative.sub("TIMESTAMP", timestamp)
  path = root.join(relative)
  abort "不正な出力パスです。" unless path.cleanpath.to_s.start_with?(root.to_s + "/")
  [path, Base64.strict_decode64(encoded)]
end
conflicts = targets.keys.select(&:exist?)
abort "同名ファイルがあるため中止しました。上書きしていません。\n#{conflicts.join("\n")}" if conflicts.any?
targets.each do |path, content|
  if path.extname == ".rb" && !Ripper.sexp(content.force_encoding("UTF-8"))
    abort "Rubyの構文確認に失敗しました: #{path}"
  end
end

backup = root.join("tmp/media_crud_backups/routes-#{timestamp}.rb")
FileUtils.mkdir_p(backup.dirname)
FileUtils.cp(routes_path, backup)
created = []
begin
  targets.each do |path, content|
    FileUtils.mkdir_p(path.dirname)
    created << path
    path.binwrite(content)
  end
  routes_path.write(new_routes)
rescue StandardError => error
  created.reverse_each { |path| FileUtils.rm_f(path) }
  routes_path.write(original_routes)
  abort "追加に失敗したため、作成したファイルを取り消しました: #{error.message}"
end

puts "追加完了: #{targets.length}個のファイルを作成しました。"
puts "Gemfile・既存のREADME・既存のアプリ用レイアウトは変更していません。"
puts "ルーティングのバックアップ: #{backup.relative_path_from(root)}"
puts "既存のトップページは維持しました。/media_items を開いてください。" if has_root
puts ""
puts "次に、同じターミナルで1行ずつ実行してください。"
puts "  bin/rails db:migrate"
puts "  bin/rails test test/models/media_item_test.rb test/controllers/media_items_controller_test.rb"
puts "  bin/rails server -b 0.0.0.0"
puts ""
puts "rails new や scaffold の実行は不要です。"
__END__
